/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The <t>PurchTable</t> table extension
/// </summary>
[ExtensionOf(dataentityviewstr(PurchPurchaseOrderHeaderV2Entity))]
final class METPurchPurchaseOrderHeaderV2Entity_Extension
{
}

Method.Source:
    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        

        METPlannerCodeSetup METPlannerCodeSetup; 

        select firstonly1 PlannerCodePersonnelNumber from METPlannerCodeSetup 
            where METPlannerCodeSetup.PlannerCode == this.METPOPlannerCode;
        
        HcmWorker HcmWorker = HcmWorker::find(METPlannerCodeSetup.PlannerCodePersonnelNumber);

        this.METPOPlannerContactName    = HcmWorker.name();
        this.METPOPlannerContactEmail   = HcmWorker.email();
        this.METPOPlannerContactPhone   = HcmWorker.phone();
        next postload();
    }

    /// <summary>
    /// getPODeliveryShiptoGLN method COC
    /// </summary>
    /// <returns> string value</returns>
    public static server str getPODeliveryShiptoGLN()
    {
        str                 locationId;
        SysDictTable        dictInventLocation = new SysDictTable(tableNum(InventLocation));
        str                 DeliveryShiptoGLN;

        locationId =  SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderHeaderV2Entity), dataEntityDataSourceStr(PurchPurchaseOrderHeaderV2Entity, PurchTable),
            fieldStr(PurchTable, InventLocationId));

        DeliveryShiptoGLN = strFmt(@"SELECT TOP 1 %1 FROM %2 WHERE %2.%3 = %4",
            dictInventLocation.fieldName(fieldNum(InventLocation, METPODeliveryShiptoGLN), DbBackend::Sql),
            dictInventLocation.name(DbBackend::Sql),
            dictInventLocation.fieldName(fieldNum(InventLocation, InventLocationId), DbBackend::Sql),
            locationId);

        return DeliveryShiptoGLN;
    }

    public void initFromVendSiteSettingSetup()
    {
        METVendSiteSettingsSetup METVendSiteSettingsSetup;

        select firstonly1 METVendSiteSettingsSetup index VendSiteWHIndex
            where (METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderVendorAccountNumber
            &&  METVendSiteSettingsSetup.AssignedSite == this.DefaultReceivingSiteId
            && METVendSiteSettingsSetup.AssignedWH == this.DefaultReceivingWarehouseId)
            || (METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderVendorAccountNumber
            &&  METVendSiteSettingsSetup.AssignedSite == this.DefaultReceivingSiteId)
            || METVendSiteSettingsSetup.AssignedVendorAccount == this.OrderVendorAccountNumber;

        if(METVendSiteSettingsSetup)
        {
            this.METPOBackOrderSetting                    = this.METPOBackOrderSetting? this.METPOBackOrderSetting: METVendSiteSettingsSetup.DefaultBackOrderSetting;
            this.METPOExpressReceiptSetting               = this.METPOExpressReceiptSetting? this.METPOExpressReceiptSetting: METVendSiteSettingsSetup.ExpressReceiptSetting;
            this.METPOASNSetting                          = this.METPOASNSetting? this.METPOASNSetting: METVendSiteSettingsSetup.ASNSetting;
            this.METPOMinOrderValue                       = this.METPOMinOrderValue? this.METPOMinOrderValue: METVendSiteSettingsSetup.MinOrderValue;
            this.METPOSubMode                             = this.METPOSubMode? this.METPOSubMode: METVendSiteSettingsSetup.POSubMode;

            if (METVendSiteSettingsSetup.POSendMethodCampaign == METConstants::Email && !this.METPOIHGEmailEDIAddress)
            {
                this.METPOIHGEmailEDIAddress  = METVendSiteSettingsSetup.POEmailAddresses;
            }
            else if (METVendSiteSettingsSetup.POSendMethodCampaign == METConstants::EDI && !this.METPOIHGEmailEDIAddress)
            {
                this.METPOIHGEmailEDIAddress  = METVendSiteSettingsSetup.POEDIAddressIHG;
            }
        }
    }

/// <summary>
///
/// </summary>
public void defaultRow()
{
    next defaultRow();
    this.initFromVendSiteSettingSetup();
}
